import {validatePath,mapPath} from './path-core.js';
export function validateDocumentData(d,source){for(const[key,max]of [['alphaChannels',16],['paths',64]]){if(d[key]===undefined)continue;if(!Array.isArray(d[key])||d[key].length>max)throw Error('Invalid '+key);const ids=new Set();for(const p of d[key]){if(!p||typeof p.id!=='string'||ids.has(p.id)||typeof p.name!=='string'||p.name.length>200)throw Error('Invalid document asset.');ids.add(p.id);if(key==='paths'){validatePath(p.commands);if(!['work','saved'].includes(p.kind))throw Error('Invalid path kind.');}else{const m=p.mask;if(!m||!['paint','rect','ellipse','polygon'].includes(m.type))throw Error('Invalid alpha.');if(m.type==='paint')source(m.source);for(const k of ['x','y','width','height','feather','density'])if(m[k]!==undefined&&(!Number.isFinite(m[k])||Math.abs(m[k])>1e7))throw Error('Invalid alpha geometry.');for(const k of ['invert','disabled','linked'])if(m[k]!==undefined&&typeof m[k]!=='boolean')throw Error('Invalid alpha flag.');if(m.density!==undefined&&(m.density<0||m.density>100)||m.feather!==undefined&&(m.feather<0||m.feather>100)||['width','height'].some(k=>m[k]!==undefined&&m[k]<1))throw Error('Invalid alpha range.');if(m.type==='polygon'&&(!Array.isArray(m.points)||m.points.length<3||m.points.length>10000||m.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)))))throw Error('Invalid alpha polygon.');}}}if(d.paths?.filter(p=>p.kind==='work').length>1)throw Error('Only one Work Path.');if(d.activePathId&&!d.paths?.some(p=>p.id===d.activePathId))d.activePathId=null;}
export function transformDocumentData(d,m){const[a,b,c,e,tx,ty]=m;for(const p of d.paths||[])p.commands=mapPath(p.commands,(x,y)=>[a*x+c*y+tx,b*x+e*y+ty]);}
